export type MarkConversationReadMutationBody = BodyType<MarkReadBody>;
export type MarkConversationReadMutationError = ErrorType<unknown>;

/**
 * @summary Mark all messages in a conversation as read for a user
 */
export const useMarkConversationRead = <
  TError = ErrorType<unknown>,
  TContext = unknown,
>(options?: {
  mutation?: UseMutationOptions<
    Awaited<ReturnType<typeof markConversationRead>>,
    TError,
    { id: number; data: BodyType<MarkReadBody> },
    TContext
  >;
  request?: SecondParameter<typeof customFetch>;
}): UseMutationResult<
  Awaited<ReturnType<typeof markConversationRead>>,
  TError,
  { id: number; data: BodyType<MarkReadBody> },
  TContext
> => {
  return useMutation(getMarkConversationReadMutationOptions(options));
};

/**
 * @summary Get messaging stats for a user
 */
export const getGetUserStatsUrl = (id: number) => {
  return `/api/users/${id}/stats`;
};

export const getUserStats = async (
  id: number,
  options?: RequestInit,
): Promise<UserStats> => {
  return customFetch<UserStats>(getGetUserStatsUrl(id), {
    ...options,
    method: "GET",
  });
};

export const getGetUserStatsQueryKey = (id: number) => {
  return [`/api/users/${id}/stats`] as const;
};

export const getGetUserStatsQueryOptions = <
  TData = Awaited<ReturnType<typeof getUserStats>>,
  TError = ErrorType<unknown>,
>(
  id: number,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getUserStats>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey = queryOptions?.queryKey ?? getGetUserStatsQueryKey(id);

  const queryFn: QueryFunction<Awaited<ReturnType<typeof getUserStats>>> = ({
    signal,
  }) => getUserStats(id, { signal, ...requestOptions });

  return {
    queryKey,
    queryFn,
    enabled: !!id,
    ...queryOptions,
  } as UseQueryOptions<
    Awaited<ReturnType<typeof getUserStats>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetUserStatsQueryResult = NonNullable<
  Awaited<ReturnType<typeof getUserStats>>
>;
export type GetUserStatsQueryError = ErrorType<unknown>;

/**
 * @summary Get messaging stats for a user
 */

export function useGetUserStats<
  TData = Awaited<ReturnType<typeof getUserStats>>,
  TError = ErrorType<unknown>,
>(
  id: number,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getUserStats>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
): UseQueryResult<TData, TError> & { queryKey: QueryKey } {
  const queryOptions = getGetUserStatsQueryOptions(id, options);

  const query = useQuery(queryOptions) as UseQueryResult<TData, TError> & {
    queryKey: QueryKey;
  };

  return { ...query, queryKey: queryOptions.queryKey };
}
